type Noun = "span" | "trace" | "session";

const NOUNS: { noun: Noun; label: string }[] = [
  { noun: "span", label: "Span" },
  { noun: "trace", label: "Trace" },
  { noun: "session", label: "Session" },
];

const WIP_NAMES: Record<Noun, string[]> = {
  span: Object.keys(WIP_ICONS).filter((name) => name.startsWith("wip-span-")),
  trace: Object.keys(WIP_ICONS).filter((name) => name.startsWith("wip-trace-")),
  session: Object.keys(WIP_ICONS).filter((name) =>
    name.startsWith("wip-session-")
  ),
};

type Selection = Record<Noun, string>;

const FAMILIES = [
  {
    id: "node-classic",
    label: "Node classic",
    icons: {
      span: "wip-span-node",
      trace: "wip-trace-node-classic",
      session: "wip-session-node-horizontal",
    },
  },
  {
    id: "node-modern",
    label: "Node modern",
    icons: {
      span: "wip-span-node",
      trace: "wip-trace-node-corner",
      session: "wip-session-node-horizontal",
    },
  },
  {
    id: "node-simple",
    label: "Node simple",
    icons: {
      span: "wip-span-node",
      trace: "wip-trace-node-separated",
      session: "wip-session-node-horizontal",
    },
  },
  {
    id: "simple",
    label: "Simple",
    icons: {
      span: "wip-span-node",
      trace: "wip-trace-node-separated",
      session: "wip-session-stack-disconnected",
    },
  },
  {
    id: "box-nested",
    label: "Box nested",
    icons: {
      span: "wip-span-box-wide",
      trace: "wip-trace-box-nested",
      session: "wip-session-stack-disconnected",
    },
  },
  {
    id: "box-offset",
    label: "Box offset",
    icons: {
      span: "wip-span-box-wide",
      trace: "wip-trace-box-offset",
      session: "wip-session-stack-disconnected",
    },
  },
] as const satisfies { id: string; label: string; icons: Selection }[];

const CUSTOM = "custom";

type Family = (typeof FAMILIES)[number]["id"] | typeof CUSTOM;

type SandboxState = { family: Family; icons: Selection };

const STORAGE_KEY = "phoenix-storybook:icon-sandbox";

const DEFAULT_STATE: SandboxState = {
  family: FAMILIES[0].id,
  icons: { ...FAMILIES[0].icons },
};

function readStoredState(): SandboxState {
  try {
    const stored = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}");
    const preset = FAMILIES.find(({ id }) => id === stored.family);
    if (preset) return { family: preset.id, icons: { ...preset.icons } };
    if (stored.family !== CUSTOM) return DEFAULT_STATE;
    const icons = { ...DEFAULT_STATE.icons };
    for (const { noun } of NOUNS) {
      if (WIP_NAMES[noun].includes(stored.icons?.[noun])) {
        icons[noun] = stored.icons[noun];
      }
    }
    return { family: CUSTOM, icons };
  } catch {
    return DEFAULT_STATE;
  }
}

// One store shared by every theme panel, so a pick in one panel updates both.
let state: SandboxState = readStoredState();
const listeners = new Set<() => void>();

function writeState(next: SandboxState) {
  state = next;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // Storage can be unavailable; the pick still applies for this session.
  }
  listeners.forEach((listener) => listener());
}

function selectIcon(noun: Noun, name: string) {
  const icons = { ...state.icons, [noun]: name };
  const preset = FAMILIES.find((family) =>
    NOUNS.every(({ noun }) => family.icons[noun] === icons[noun])
  );
  writeState({ family: preset?.id ?? CUSTOM, icons });
}

function selectFamily(family: Family) {
  const preset = FAMILIES.find(({ id }) => id === family);
  writeState({ family, icons: preset ? { ...preset.icons } : state.icons });
}

// The Docs page and the canvas are separate iframes; `storage` fires in every
// other document of the origin, keeping their picks in step.
window.addEventListener("storage", (event) => {
  if (event.key !== STORAGE_KEY) return;
  state = readStoredState();
  listeners.forEach((listener) => listener());
});

function useSandboxState(): SandboxState {
  return useSyncExternalStore(
    (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    () => state
  );
}

function NounIcon({ name }: { name: string }) {
  const Glyph = WIP_ICONS[name];
  return <Icon svg={<Glyph />} />;
}

function glyph(name: string) {
  const Glyph = WIP_ICONS[name];
  return <Glyph />;
}

